"import { Client } from 'ssh2';
import fs from 'fs';
import path from 'path';

const conn = new Client();
conn.on('ready', () => {
  const code = `
    const net = require('net');
    const s = net.createConnection(23, '172.19.60.2', () => {
      s.write('admin\\r\\nCloudWare1991\\r\\nenable\\r\\nterminal length 0\\r\\nshow running-config\\r\\nexit\\r\\n');
    });
    let out = '';
    s.on('data', d => out += d.toString('utf8'));
    setTimeout(() => {
      console.log('--- BACKUP_START ---');
      console.log(out);
      console.log('--- BACKUP_END ---');
      process.exit(0);
    }, 6000);
  `;

  conn.exec(`docker exec -i chatbot_app node -e "${code.replace(/\n/g, ' ')}"`, (err, stream) => {
    if (err) throw err;
    let fullOutput = '';
    stream.on('data', d => fullOutput += d.toString());
    stream.stderr.on('data', d => fullOutput += d.toString());
    stream.on('close', () => {
      conn.end();
      const startTag = '--- BACKUP_START ---';
      const endTag = '--- BACKUP_END ---';
      const sIdx = fullOutput.indexOf(startTag);
      const eIdx = fullOutput.indexOf(endTag);

      let configText = fullOutput;
      if (sIdx !== -1 && eIdx !== -1) {
        configText = fullOutput.substring(sIdx + startTag.length, eIdx).trim();
      }

      const backupDir = path.resolve('backups/olt');
      if (!fs.existsSync(backupDir)) {
        fs.mkdirSync(backupDir, { recursive: true });
      }

      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      const filename = path.join(backupDir, `olt-backup-${timestamp}.cfg`);
      fs.writeFileSync(filename, configText, 'utf8');
      console.log(`\n✅ Respaldo de OLT guardado con éxito en: ${filename}`);
      console.log(`Tamaño: ${configText.length} bytes`);
      process.exit(0);
    });
  });
}).connect({
  host: '2.25.241.239',
  port: 22,
  username: 'root',
  password: 'CloudWare1991@'
});
"

